function save(){localStorage.setItem(KEY,JSON.stringify(items));}
function syncFilt(){document.querySelectorAll('.${r}filt').forEach(b=>{const on=b.dataset.f===filter;b.className='btn ${r}filt'+(on?'':' btn-ghost');b.style.cssText='padding:0.35rem 0.65rem;font-size:0.75rem';});}
