document.getElementById('${r}add-form').addEventListener('submit',e=>{e.preventDefault();const input=document.getElementById('${r}task');const text=input.value.trim();if(!text)return;items.unshift({text,done:false});input.value='';save();render();input.focus();});
document.getElementById('${r}clear-done').addEventListener('click',()=>{items=items.filter(x=>!x.done);save();render();});
